const TABLE: [(&str, u32); 3] = [("apples", 3), ("pears", 5), ("plums", 2)];

fn csv_field(field: &str) -> String {
    if field.contains([',', '"', '\n', '\r']) {
        format!("\"{}\"", field.replace('"', "\"\""))
    } else {
        field.to_owned()
    }
}

fn export_csv(table: &[(&str, u32)]) -> String {
    let mut output = String::from("fruit,count\n");
    for (name, count) in table {
        output.push_str(&csv_field(name));
        output.push(',');
        output.push_str(&count.to_string());
        output.push('\n');
    }
    output
}

fn main() {
    print!("{}", export_csv(&TABLE));
}

#[cfg(test)]
mod tests {
    use super::export_csv;

    #[test]
    fn exports_ordinary_values_with_header() {
        assert_eq!(
            export_csv(&[("apples", 3), ("pears", 5)]),
            "fruit,count\napples,3\npears,5\n"
        );
    }

    #[test]
    fn escapes_csv_special_characters() {
        assert_eq!(
            export_csv(&[("sweet, red", 1), ("ripe \"golden\"", 2), ("line\nbreak", 3)]),
            "fruit,count\n\"sweet, red\",1\n\"ripe \"\"golden\"\"\",2\n\"line\nbreak\",3\n"
        );
    }
}
